<?php require_once __DIR__.'/../app/App.php'; if(Auth::platformCheck())redirect('platform.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{Auth::platformLogin(AppContext::api(),trim($_POST['email']??''),$_POST['password']??'');redirect('platform.php');}catch(Throwable $e){$error=$e->getMessage();}} ?><!doctype html><html><head><meta charset="utf-8"><title>PassNow Platform</title><style>body{font-family:Arial;background:#f5f6f8;display:grid;place-items:center;height:100vh;margin:0}.card{background:#fff;padding:32px;width:340px;border-radius:12px;box-shadow:0 8px 30px #0001}input,button{width:100%;padding:12px;margin:8px 0;box-sizing:border-box}button{background:#111;color:#fff;border:0;border-radius:6px}.err{color:#b42318}</style></head><body><form class="card" method="post"><h2>PassNow Platform</h2><p>Platform administrator login</p><?php if($error):?><p class="err"><?=htmlspecialchars($error)?></p><?php endif?><input type="email" name="email" placeholder="Email" required><input type="password" name="password" placeholder="Password" required><button>Sign in</button></form></body></html>